//! Build script: finds the Rust viz plugin folders.
//!
//! Each folder `src/viz/plugins/<snake_name>/` that contains a `mod.rs` is a
//! plugin (the rules are in `src/viz/plugins/README.md`). This script writes
//! `$OUT_DIR/viz_plugins.rs`, which `src/viz/plugins/mod.rs` includes. The
//! generated file holds:
//!
//! * a `#[path = ".../mod.rs"] pub mod <snake_name>;` line per folder, and
//! * `pub fn register_all() -> Vec<RegisterError>`, which registers each
//!   folder's plugin with the registry.
//!
//! Why generate it: a contributor adds a folder and edits no shared file, so
//! two plugin branches never conflict on a module list.
//!
//! The script has no dependencies and runs for every build, including builds
//! without the `tui` feature. In those builds the generated file is never
//! compiled, because `src/viz` is gated on `tui`.

use std::fs;
use std::path::Path;

fn main() {
    // Rebuild when a folder is added, removed or edited. Cargo scans the
    // directory tree for changes.
    println!("cargo:rerun-if-changed=src/viz/plugins");
    println!("cargo:rerun-if-changed=build.rs");

    let manifest = std::env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR is set by cargo");
    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR is set by cargo");
    let plugins_dir = Path::new(&manifest).join("src/viz/plugins");

    // Folder names that hold a mod.rs, sorted so the output is stable.
    let mut names: Vec<String> = Vec::new();
    if let Ok(read) = fs::read_dir(&plugins_dir) {
        for item in read.flatten() {
            let path = item.path();
            if path.is_dir() && path.join("mod.rs").is_file() {
                let name = item.file_name().to_string_lossy().to_string();
                if !is_snake_ident(&name) {
                    panic!(
                        "plugin folder `{name}` must be snake_case: lowercase letters, \
                         digits and `_`, starting with a letter (see src/viz/plugins/README.md)"
                    );
                }
                names.push(name);
            }
        }
    }
    names.sort();

    let mut code = String::new();
    code.push_str("// Generated by build.rs. Do not edit.\n\n");
    for name in &names {
        // `#[path]` takes the absolute path. Backslashes become forward
        // slashes so the string literal is valid on Windows too.
        let path = plugins_dir
            .join(name)
            .join("mod.rs")
            .to_string_lossy()
            .replace('\\', "/");
        code.push_str(&format!("#[path = \"{path}\"]\npub mod {name};\n"));
    }
    code.push_str(
        "\n/// Register every plugin folder. Returns the errors for the caller to log.\n\
         pub fn register_all() -> Vec<crate::viz::RegisterError> {\n",
    );
    // With no folders there is nothing to push to; a bare `Vec::new()` keeps
    // `unused_mut` and clippy's `let_and_return` quiet in that case.
    if names.is_empty() {
        code.push_str("    Vec::new()\n}\n");
    } else {
        code.push_str("    let mut errors = Vec::new();\n");
    }
    for name in &names {
        // The id comes from the plugin itself; the README requires it to
        // equal the folder name with `_` replaced by `-`.
        code.push_str(&format!(
            "    {{\n\
             \x20       let probe = {name}::make();\n\
             \x20       let id = probe.id().to_string();\n\
             \x20       let title = probe.title().to_string();\n\
             \x20       drop(probe);\n\
             \x20       if let Err(e) = crate::viz::registry::register(\n\
             \x20           &id,\n\
             \x20           &title,\n\
             \x20           crate::viz::Source::Folder,\n\
             \x20           {name}::ENABLED_BY_DEFAULT,\n\
             \x20           Box::new({name}::make),\n\
             \x20       ) {{\n\
             \x20           errors.push(e);\n\
             \x20       }}\n\
             \x20   }}\n"
        ));
    }
    if !names.is_empty() {
        code.push_str("    errors\n}\n");
    }

    fs::write(Path::new(&out_dir).join("viz_plugins.rs"), code)
        .expect("write $OUT_DIR/viz_plugins.rs");
}

/// True for a valid snake_case Rust module name: starts with a lowercase
/// letter, then lowercase letters, digits or `_`.
fn is_snake_ident(s: &str) -> bool {
    let mut chars = s.chars();
    matches!(chars.next(), Some(c) if c.is_ascii_lowercase())
        && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
}
